\set ON_ERROR_STOP on
-- AD3-121: cierra la búsqueda de tipos de la clausura externa.
-- Conserva cuerpos, firmas, OID, propietarios, ACL, canon e historia.
-- Requiere AD3-116 y AUT20. No reaplicar sobre una instalación ya corregida.
BEGIN;
SET LOCAL search_path=pg_catalog,pg_temp;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SELECT pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('autorizacion_atestada_v3:migracion:externa:000121',0));
DO $correctiva$
DECLARE esperado record; antes record; despues record; acl_actual pg_catalog.jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper)
    OR pg_catalog.current_setting('transaction_isolation')<>'read committed'
    OR pg_catalog.to_regrole('vec_autorizacion_atestada_v3_propietario') IS NULL THEN
  RAISE EXCEPTION 'AD3-121: migrador no autorizado' USING ERRCODE='55000';
 END IF;
