  ('vec_autorizacion_atestada_v3.capacidad_canonica(jsonb)','aa7ba0652224c93fc4d1f0bec46049aac24e93b7abdd4955eebb718be0527fd8',false,'["search_path=pg_catalog"]'::jsonb,'[{"grantee": "vec_autorizacion_atestada_v3_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
  ('vec_autorizacion_atestada_v3.capacidad_cruda_prevalida(bytea)','2c44c59293746b836647a9922c5fbb833ce1aae7e42a9ecfe7c8ab659263acb6',false,'["search_path=pg_catalog"]'::jsonb,'[{"grantee": "vec_autorizacion_atestada_v3_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
  ('vec_autorizacion_atestada_v3.capacidad_tipos_validos(jsonb)','b9c331a9cbd635abc8325e9233bcabd38a3bc10215c0cc49929871f22410c669',false,'["search_path=pg_catalog"]'::jsonb,'[{"grantee": "vec_autorizacion_atestada_v3_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
  ('vec_autorizacion_atestada_v3.comprobar_material_emision_externa_v1(text,jsonb)','0ba180fec6ecd5328ab084e2b2e1cf3ec8f8cefec1fd603cf176e9741c5832e7',true,'["search_path=pg_catalog", "lock_timeout=2s"]'::jsonb,'[{"grantee": "vec_autorizacion_atestada_v3_preflight_externo", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "vec_autorizacion_atestada_v3_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
  ('vec_autorizacion_atestada_v3.encuadrar_mac(text)','1d580fb6f1dd53f3c7a7933772a3d6649effb3ad10ffec42df534f8dab3ec69d',false,'["search_path=pg_catalog"]'::jsonb,'[{"grantee": "vec_autorizacion_atestada_v3_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
  ('vec_autorizacion_atestada_v3.huella_sha256_valida(text)','003b525f9d89dd4faf913f17675cafe60479d8ab17c09cf746deb23bf310dfe8',false,'["search_path=pg_catalog"]'::jsonb,'[{"grantee": "vec_autorizacion_atestada_v3_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
  ('vec_autorizacion_atestada_v3.leer_configuracion_externa_v1(text,jsonb)','f64428afaf5871119ff7a6c8e04bdda98616ca4a151c6e2bd23dd308d37bb3ee',true,'["search_path=pg_catalog", "lock_timeout=2s"]'::jsonb,'[{"grantee": "vec_autorizacion_atestada_v3_preflight_externo", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "vec_autorizacion_atestada_v3_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
  ('vec_autorizacion_atestada_v3.preimagen_mac(jsonb)','45a23c36c1d42bdb63e4cc2f7e72cb155dc6f779f021261815980adec7506418',false,'["search_path=pg_catalog"]'::jsonb,'[{"grantee": "vec_autorizacion_atestada_v3_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
