  ('vec_autorizacion_atestada_v3.registrar_y_consumir_historial_propio_bolsa_v3_atestada(bytea,bytea,bytea,bytea,numeric,numeric,bytea,bytea,bytea,bytea)','8dfe36c0e95446e25a51e61abe45d6f97822527fd91d0314e41ec2fdb23be138',true,'["search_path=pg_catalog", "lock_timeout=2s"]'::jsonb,'[{"grantee": "vec_autorizacion_atestada_v3_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "vec_bolsa_llamamientos_propietario", "grantor": "vec_autorizacion_atestada_v3_propietario", "grantable": false, "privilege": "EXECUTE"}]'::jsonb),
