ic"},{"desde":125902,"tipo":"numeric","nuevo":"pg_catalog.numeric"},{"desde":126160,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":126249,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":126509,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":126583,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":126740,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":126821,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":126890,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":126959,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":128232,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":128298,"tipo":"timestamptz","nuevo":"pg_catalog.timestamptz"},{"desde":131549,"tipo":"numeric","nuevo":"pg_catalog.numeric"},{"desde":131904,"tipo":"text","nuevo":"pg_catalog.text"}]}]'::jsonb)
 ) AS inventario(firma,definidor,configuracion,acl,variantes) LOOP
  SELECT p.* INTO STRICT antes FROM pg_catalog.pg_proc p WHERE p.oid=pg_catalog.to_regprocedure(esperado.firma);
  SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'grantee',r.rolname,'grantor',g.rolname,'grantable',a.is_grantable,'privilege',a.privilege_type)
    ORDER BY r.rolname,g.rolname,a.privilege_type,a.is_grantable),'[]'::pg_catalog.jsonb)
  INTO acl_actual FROM pg_catalog.aclexplode(coalesce(antes.proacl,pg_catalog.acldefault('f',antes.proowner))) a
  LEFT JOIN pg_catalog.pg_roles r ON r.oid=a.grantee LEFT JOIN pg_catalog.pg_roles g ON g.oid=a.grantor;
  huella:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(antes.prosrc,'UTF8')),'hex');
  SELECT v INTO variante FROM pg_catalog.jsonb_array_elements(esperado.variantes) v WHERE v->>'antes'=huella;
  IF NOT FOUND OR antes.proowner IS DISTINCT FROM pg_catalog.to_regrole('vec_autorizacion_atestada_v3_propietario')
     OR antes.prosecdef IS DISTINCT FROM esperado.definidor
     OR pg_catalog.to_jsonb(antes.proconfig) IS DISTINCT FROM esperado.configuracion
     OR acl_actual IS DISTINCT FROM esperado.acl THEN
   RAISE EXCEPTION 'AD3-121: preimagen incompatible para %',esperado.firma USING ERRCODE='55000';
  END IF;
  fuente:=antes.prosrc;
  FOR cambio IN SELECT c FROM pg_catalog.jsonb_array_elements(variante->'cambios') c ORDER BY (c->>'desde')::pg_catalog.int4 DESC LOOP
   inicio:=(cambio->>'desde')::pg_catalog.int4;
   IF pg_catalog.substr(fuente,inicio,pg_catalog.length(cambio->>'tipo')) IS DISTINCT FROM cambio->>'tipo' THEN
    RAISE EXCEPTION 'AD3-121: tipo incompatible para %',esperado.firma USING ERRCODE='55000';
   END IF;
   fuente:=pg_catalog.substr(fuente,1,inicio-1)||(cambio->>'nuevo')||pg_catalog.substr(fuente,inicio+pg_catalog.length(cambio->>'tipo'));
  END LOOP;
  IF pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(fuente,'UTF8')),'hex') IS DISTINCT FROM variante->>'despues' THEN
   RAISE EXCEPTION 'AD3-121: huella de cuerpo incompatible para %',esperado.firma USING ERRCODE='55000';
  END IF;
  definicion:=pg_catalog.pg_get_functiondef(antes.oid);
  IF (pg_catalog.length(definicion)-pg_catalog.length(pg_catalog.replace(definicion,antes.prosrc,'')))<>pg_catalog.length(antes.prosrc) THEN
   RAISE EXCEPTION 'AD3-121: definición incompatible para %',esperado.firma USING ERRCODE='55000';
  END IF;
  EXECUTE pg_catalog.replace(definicion,antes.prosrc,fuente);
  SELECT p.* INTO STRICT despues FROM pg_catalog.pg_proc p WHERE p.oid=antes.oid;
  IF despues.prosrc IS DISTINCT FROM fuente
     OR pg_catalog.to_jsonb(despues)-'prosrc' IS DISTINCT FROM pg_catalog.to_jsonb(antes)-'prosrc' THEN
   RAISE EXCEPTION 'AD3-121: postimagen incompatible para %',esperado.firma USING ERRCODE='55000';
  END IF;
 END LOOP;
END $tipos_consumidores$;
COMMIT;
